using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

namespace Screenbox.Core.Services;

/// <summary>
/// Holds the ASS files generated by the subtitle resizer, under the app's temporary folder.
/// A file is identified by the MRL that LibVLC opens it with.
/// </summary>
public interface IResizedSubtitleStore
{
    /// <summary>Writes a generated file.</summary>
    /// <param name="content">The text of the ASS file.</param>
    /// <param name="cancellationToken">Cancels the write.</param>
    /// <returns>The MRL to load the file with.</returns>
    Task<string> WriteAsync(string content, CancellationToken cancellationToken);

    /// <summary>
    /// Deletes files that are no longer needed. A file VLC still holds open stays until
    /// <see cref="DeleteAllAsync"/> next runs, which is not an error.
    /// </summary>
    /// <param name="mrls">The MRLs returned by <see cref="WriteAsync"/>.</param>
    Task ReleaseAsync(IReadOnlyCollection<string> mrls);

    /// <summary>Deletes every generated file, including any left by an earlier session.</summary>
    Task DeleteAllAsync();
}
